import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;
import javax.swing.plaf.basic.BasicButtonUI;

public class StudentRecordApp extends JFrame {
    private final JTextField id=new JTextField(), name=new JTextField(), email=new JTextField(), course=new JTextField(), phone=new JTextField(), filter=new JTextField(18);
    private final DefaultTableModel data=new DefaultTableModel(new String[]{"ID","Full name","Email","Course","Phone"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(data); private final JLabel status=new JLabel("Ready");
    private final String url=env("DB_URL","jdbc:mysql://localhost:3306/student_records?serverTimezone=UTC&useSSL=false&allowPublicKeyRetrieval=true"), user=env("DB_USER","root"), password=env("DB_PASSWORD","");
    private static String env(String k,String d){String v=System.getenv(k);return v==null?d:v;}
    private StudentRecordApp(){
        super("Student Record Manager");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,680);setMinimumSize(new Dimension(850,560));setLocationRelativeTo(null);
        getContentPane().setBackground(new Color(246,248,252));setLayout(new BorderLayout());
        JLabel title=new JLabel("Student Record Manager");title.setFont(new Font("Segoe UI",Font.BOLD,24));title.setForeground(Color.WHITE);
        JLabel subtitle=new JLabel("Manage student information in one place");subtitle.setForeground(new Color(199,210,228));
        JPanel head=new JPanel();head.setLayout(new BoxLayout(head,BoxLayout.Y_AXIS));head.setBackground(new Color(22,34,56));head.setBorder(BorderFactory.createEmptyBorder(18,26,18,18));head.add(title);head.add(Box.createVerticalStrut(4));head.add(subtitle);add(head,BorderLayout.NORTH);
        JPanel root=new JPanel(new BorderLayout(0,14));root.setBackground(new Color(246,248,252));root.setBorder(BorderFactory.createEmptyBorder(20,24,14,24));add(root,BorderLayout.CENTER);
        JPanel form=new JPanel(new BorderLayout(8,10));form.setBackground(Color.WHITE);form.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(226,231,239)),BorderFactory.createEmptyBorder(16,18,16,18)));
        JLabel details=new JLabel("Student details");details.setFont(new Font("Segoe UI",Font.BOLD,16));
        JPanel fields=new JPanel(new GridLayout(2,3,14,10));fields.setOpaque(false);addField(fields,"Student ID (optional on add)",id);addField(fields,"Full name *",name);addField(fields,"Email",email);addField(fields,"Course",course);addField(fields,"Phone",phone);
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));buttons.setOpaque(false);addButton(buttons,"Add",new Color(49,95,170),this::addStudent);addButton(buttons,"Search by ID",new Color(69,119,107),this::search);addButton(buttons,"Update",new Color(174,117,40),this::update);addButton(buttons,"Delete",new Color(173,69,76),this::delete);addButton(buttons,"Clear",new Color(102,113,131),this::clear);
        JPanel body=new JPanel(new BorderLayout(0,12));body.setOpaque(false);body.add(fields,BorderLayout.CENTER);body.add(buttons,BorderLayout.SOUTH);form.add(details,BorderLayout.NORTH);form.add(body,BorderLayout.CENTER);root.add(form,BorderLayout.NORTH);
        JPanel records=new JPanel(new BorderLayout(0,10));records.setBackground(Color.WHITE);records.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(226,231,239)),BorderFactory.createEmptyBorder(15,18,16,18)));
        JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));tools.setOpaque(false);JLabel h=new JLabel("Student records");h.setFont(new Font("Segoe UI",Font.BOLD,16));tools.add(h);tools.add(Box.createHorizontalStrut(20));tools.add(new JLabel("Quick filter"));filter.setPreferredSize(new Dimension(200,30));tools.add(filter);JButton f=new JButton("Filter");styleButton(f,new Color(64,85,115));f.addActionListener(e->filterRecords());tools.add(f);JButton view=new JButton("View all");styleButton(view,new Color(64,85,115));view.addActionListener(e->load());tools.add(view);filter.addActionListener(e->filterRecords());
        table.setRowHeight(36);table.setFont(new Font("Segoe UI",Font.PLAIN,14));table.setForeground(new Color(28,39,55));table.setBackground(Color.WHITE);table.setGridColor(new Color(218,225,235));table.setSelectionBackground(new Color(48,92,158));table.setSelectionForeground(Color.WHITE);table.setShowGrid(true);table.setFillsViewportHeight(true);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setAutoCreateRowSorter(true);table.getTableHeader().setReorderingAllowed(false);table.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,13));table.getTableHeader().setForeground(new Color(30,44,65));table.getTableHeader().setBackground(new Color(231,237,246));table.getTableHeader().setPreferredSize(new Dimension(0,38));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)fill();});records.add(tools,BorderLayout.NORTH);records.add(new JScrollPane(table),BorderLayout.CENTER);root.add(records,BorderLayout.CENTER);status.setFont(new Font("Segoe UI",Font.PLAIN,12));status.setForeground(new Color(52,65,84));status.setBackground(Color.WHITE);status.setOpaque(true);status.setBorder(BorderFactory.createEmptyBorder(9,24,9,24));add(status,BorderLayout.SOUTH);load();
    }
    private void addField(JPanel p,String label,JTextField f){JPanel b=new JPanel(new BorderLayout(0,4));b.setOpaque(false);JLabel l=new JLabel(label);l.setFont(new Font("Segoe UI",Font.BOLD,13));l.setForeground(new Color(47,59,77));f.setFont(new Font("Segoe UI",Font.PLAIN,14));f.setForeground(new Color(25,35,50));f.setBackground(Color.WHITE);f.setCaretColor(new Color(25,35,50));f.setPreferredSize(new Dimension(160,34));b.add(l,BorderLayout.NORTH);b.add(f,BorderLayout.CENTER);p.add(b);}
    private void addButton(JPanel p,String text,Color color,Runnable action){JButton b=new JButton(text);styleButton(b,color);b.addActionListener(e->action.run());p.add(b);}
    private void styleButton(JButton b,Color color){b.setUI(new BasicButtonUI());b.setOpaque(true);b.setContentAreaFilled(true);b.setBorderPainted(false);b.setBackground(color);b.setForeground(Color.WHITE);b.setFocusPainted(false);b.setFont(new Font("Segoe UI",Font.BOLD,13));b.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(color.darker()),BorderFactory.createEmptyBorder(9,14,9,14)));b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));}
    private Connection connect()throws SQLException{return DriverManager.getConnection(url,user,password);}
    private boolean valid(){if(name.getText().trim().isEmpty()){error("Full name is required.");name.requestFocus();return false;}String x=email.getText().trim();if(!x.isEmpty()&&!x.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")){error("Enter a valid email address.");return false;}return true;}
    private int getId(){try{int n=Integer.parseInt(id.getText().trim());if(n>0)return n;}catch(Exception ignored){}error("Enter a positive whole-number student ID.");return -1;}
    private void addStudent(){if(!valid())return;boolean manual=!id.getText().trim().isEmpty();if(manual){try{if(getId()<0)return;}catch(Exception e){return;}}String sql=manual?"INSERT INTO students(student_id,full_name,email,course,phone) VALUES(?,?,?,?,?)":"INSERT INTO students(full_name,email,course,phone) VALUES(?,?,?,?)";try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){int i=1;if(manual)p.setInt(i++,Integer.parseInt(id.getText().trim()));bind(p,i);p.executeUpdate();String created=id.getText();if(!manual)try(ResultSet k=p.getGeneratedKeys()){if(k.next())created=k.getString(1);}load();clear();status.setText("Student "+created+" added.");}catch(SQLException e){dbError(e);}}
    private void search(){int n=getId();if(n<0)return;try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT student_id,full_name,email,course,phone FROM students WHERE student_id=?")){p.setInt(1,n);try(ResultSet r=p.executeQuery()){data.setRowCount(0);if(r.next()){row(r);table.setRowSelectionInterval(0,0);status.setText("Student found.");}else{clear();status.setText("No student found with ID "+n+".");}}}catch(SQLException e){dbError(e);}}
    private void update(){int n=getId();if(n<0||!valid())return;try(Connection c=connect();PreparedStatement p=c.prepareStatement("UPDATE students SET full_name=?,email=?,course=?,phone=? WHERE student_id=?")){bind(p,1);p.setInt(5,n);if(p.executeUpdate()==0)status.setText("No student found with ID "+n+".");else{load();status.setText("Student updated.");}}catch(SQLException e){dbError(e);}}
    private void delete(){int n=getId();if(n<0)return;if(JOptionPane.showConfirmDialog(this,"Delete student "+n+"?","Confirm deletion",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM students WHERE student_id=?")){p.setInt(1,n);if(p.executeUpdate()==0)status.setText("No student found with ID "+n+".");else{load();clear();status.setText("Student deleted.");}}catch(SQLException e){dbError(e);}}
    private void load(){query("SELECT student_id,full_name,email,course,phone FROM students ORDER BY student_id",null);}
    private void filterRecords(){String q=filter.getText().trim();if(q.isEmpty()){load();return;}query("SELECT student_id,full_name,email,course,phone FROM students WHERE full_name LIKE ? OR email LIKE ? OR course LIKE ? OR phone LIKE ? ORDER BY student_id",q);}
    private void query(String sql,String q){try(Connection c=connect();PreparedStatement p=c.prepareStatement(sql)){if(q!=null)for(int i=1;i<=4;i++)p.setString(i,"%"+q+"%");try(ResultSet r=p.executeQuery()){data.setRowCount(0);while(r.next())row(r);}status.setText("Showing "+data.getRowCount()+" record(s).");}catch(SQLException e){dbError(e);}}
    private void bind(PreparedStatement p,int i)throws SQLException{p.setString(i++,name.getText().trim());nullable(p,i++,email.getText());nullable(p,i++,course.getText());nullable(p,i,phone.getText());}
    private void nullable(PreparedStatement p,int i,String s)throws SQLException{if(s.trim().isEmpty())p.setNull(i,Types.VARCHAR);else p.setString(i,s.trim());}
    private void row(ResultSet r)throws SQLException{data.addRow(new Object[]{r.getInt("student_id"),r.getString("full_name"),r.getString("email"),r.getString("course"),r.getString("phone")});}
    private void fill(){int r=table.convertRowIndexToModel(table.getSelectedRow());id.setText(at(r,0));name.setText(at(r,1));email.setText(at(r,2));course.setText(at(r,3));phone.setText(at(r,4));}
    private String at(int r,int c){Object v=data.getValueAt(r,c);return v==null?"":v.toString();}
    private void clear(){id.setText("");name.setText("");email.setText("");course.setText("");phone.setText("");table.clearSelection();}
    private void dbError(SQLException e){error("Database operation failed: "+e.getMessage()+"\n\nCheck MySQL is running, database/schema.sql has been run, and DB_USER / DB_PASSWORD are correct.");status.setText("Database operation failed.");}
    private void error(String m){JOptionPane.showMessageDialog(this,m,"Student Record Manager",JOptionPane.ERROR_MESSAGE);}
    public static void main(String[] a){try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}SwingUtilities.invokeLater(()->new StudentRecordApp().setVisible(true));}
}
